import{_ as a,a as t,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"我在故宫修文物（剧集版）","description":"镜头从展柜中的成品转向文物修复工作室，观察钟表、书画、青铜、木器等修复人员的日常。清理、比对、试验和等待构成工作的主要节奏，许多成果并不能在很短时间内完成。","frontmatter":{"title":"我在故宫修文物（剧集版）","description":"镜头从展柜中的成品转向文物修复工作室，观察钟表、书画、青铜、木器等修复人员的日常。清理、比对、试验和等待构成工作的主要节奏，许多成果并不能在很短时间内完成。","media":{"category":"documentaries","year":2016,"doubanRating":9.4,"ratingCheckedAt":"2026-10-31","ratingSource":"https://finance.sina.com.cn/tech/roll/2026-04-20/doc-inhvcmee0662433.shtml","ratingSourceType":"媒体转引"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 纪录片","summary":"镜头从展柜中的成品转向文物修复工作室，观察钟表、书画、青铜、木器等修复人员的日常。清理、比对、试验和等待构成工作的主要节奏，许多成果并不能在很短时间内完成。","status":"active","related":[{"title":"地球脉动 第二季","link":"/life/personal/media/documentaries/planet-earth-2","kind":"影视导读","scope":"general","audience":"general"},{"title":"蓝色星球 第二季","link":"/life/personal/media/documentaries/blue-planet-2","kind":"影视导读","scope":"general","audience":"general"},{"title":"猎捕","link":"/life/personal/media/documentaries/the-hunt","kind":"影视导读","scope":"general","audience":"general"},{"title":"河西走廊","link":"/life/personal/media/documentaries/hexi-corridor","kind":"影视导读","scope":"general","audience":"general"},{"title":"冰冻星球 第一季","link":"/life/personal/media/documentaries/frozen-planet-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"七个世界，一个星球","link":"/life/personal/media/documentaries/seven-worlds-one-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"宇宙时空之旅","link":"/life/personal/media/documentaries/cosmos-a-spacetime-odyssey","kind":"影视导读","scope":"general","audience":"general"},{"title":"人类星球","link":"/life/personal/media/documentaries/human-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们的星球 第一季","link":"/life/personal/media/documentaries/our-planet-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"绿色星球","link":"/life/personal/media/documentaries/the-green-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"生命故事","link":"/life/personal/media/documentaries/life-story","kind":"影视导读","scope":"general","audience":"general"},{"title":"人间世 第一季","link":"/life/personal/media/documentaries/life-matters-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"生命（2009）","link":"/life/personal/media/documentaries/life-2009","kind":"影视导读","scope":"general","audience":"general"},{"title":"完美星球","link":"/life/personal/media/documentaries/a-perfect-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"王朝 第一季","link":"/life/personal/media/documentaries/dynasties-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"舌尖上的中国 第一季","link":"/life/personal/media/documentaries/a-bite-of-china-season-1","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"舌尖上的中国 第一季","link":"/life/personal/media/documentaries/a-bite-of-china-season-1"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"舌尖上的中国 第一季","link":"/life/personal/media/documentaries/a-bite-of-china-season-1"},"next":false},"headers":[],"relativePath":"life/personal/media/documentaries/masters-in-the-forbidden-city.md","filePath":"life/personal/media/documentaries/masters-in-the-forbidden-city.md"}'),i={name:"life/personal/media/documentaries/masters-in-the-forbidden-city.md"};function l(d,e,o,s,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="我在故宫修文物-剧集版" tabindex="-1">我在故宫修文物（剧集版） <a class="header-anchor" href="#我在故宫修文物-剧集版" aria-label="Permalink to &quot;我在故宫修文物（剧集版）&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">纪录片片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>Masters in the Forbidden City</td></tr><tr><td>年份 / 地区</td><td>2016 / 中国大陆</td></tr><tr><td>类型</td><td>文物 / 工艺 / 人文</td></tr><tr><td>导演 / 主创</td><td>叶君、萧寒</td></tr><tr><td>篇幅 / 版本</td><td>3 集，单集约 50 分钟；与同名电影版分开</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.4 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://finance.sina.com.cn/tech/roll/2026-04-20/doc-inhvcmee0662433.shtml" target="_blank" rel="noopener noreferrer">新浪科技2026年报道转引的豆瓣评分</a>（媒体转引）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为公开资料转引或历史快照，已于本次查询核对来源文字，未核实豆瓣实时值；来源时间与查询日期不是同一概念。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>这篇介绍对应 2016 年首播的三集电视纪录片。<a href="https://www.artmuseum.tsinghua.edu.cn/ggjy/ybyh/hdyg/201705/t20170505_2472.shtml" target="_blank" rel="noopener noreferrer">清华大学艺术博物馆的放映与主创分享资料</a>列出剧集信息，并概括青铜器、钟表、书画、木器、陶瓷、漆器、镶嵌和织绣等修复门类。它与同名电影的篇幅和剪辑不同。</p><p>片名里的“我”将镜头从宏大的宫殿移到具体劳动者身上。观众进入的不是帝王故事，而是一间间工作室：历史物件需要在今天被研究、照看和继续保存。</p><h2 id="内容介绍" tabindex="-1">内容介绍 <a class="header-anchor" href="#内容介绍" aria-label="Permalink to &quot;内容介绍&quot;">​</a></h2><p>镜头从展柜中的成品转向文物修复工作室，观察钟表、书画、青铜、木器等修复人员的日常。清理、比对、试验和等待构成工作的主要节奏，许多成果并不能在很短时间内完成。</p><p>节目也拍摄师徒相处和普通生活，让修复师从抽象的工匠符号变为具体的人。面对历史留下的材料，他们既需要技术和审美，也需要知道何时应克制自己的改动。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-观察视角" tabindex="-1">1. 观察视角 <a class="header-anchor" href="#_1-观察视角" aria-label="Permalink to &quot;1. 观察视角&quot;">​</a></h3><p>修复并不等于把旧物做得像新的一样。可以留意人物怎样解释痕迹、原有结构和后人介入之间的关系，理解保护工作中的判断与边界。</p><h3 id="_2-表达与理解" tabindex="-1">2. 表达与理解 <a class="header-anchor" href="#_2-表达与理解" aria-label="Permalink to &quot;2. 表达与理解&quot;">​</a></h3><p>工作室里的重复动作、休息和闲谈使专业技能具有时间感。片子没有持续制造刺激，观众也需要调整节奏，才能看见那些细小但重要的决定。</p><h2 id="不同门类怎样形成观看重点" tabindex="-1">不同门类怎样形成观看重点 <a class="header-anchor" href="#不同门类怎样形成观看重点" aria-label="Permalink to &quot;不同门类怎样形成观看重点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门类线索</th><th>可以留意的工作问题</th></tr></thead><tbody><tr><td>钟表与金属器物</td><td>怎样理解原有结构，判断损伤与功能之间的关系？</td></tr><tr><td>书画与织绣</td><td>脆弱材料如何被托住、整理和保存？</td></tr><tr><td>木器、陶瓷与漆器</td><td>缺损、接合和表面痕迹怎样影响修复选择？</td></tr></tbody></table><p>不同材料面对的问题不相同，不能用“修得越完整越好”来概括所有工作。节目最值得慢看的部分，是专业人员如何在动手前反复观察、比较与商量，承认不知道的部分，再决定介入到哪一步。</p><h2 id="钟表、书画与师徒日常" tabindex="-1">钟表、书画与师徒日常 <a class="header-anchor" href="#钟表、书画与师徒日常" aria-label="Permalink to &quot;钟表、书画与师徒日常&quot;">​</a></h2><p>钟表修复的吸引力在于，静态文物内部还有一套精细运作的关系。零件是否能动并不是唯一问题，理解原来的连接方式与留下的痕迹同样重要。看见机械重新运作时，可以回想此前有多少并不显眼的检查与试验。</p><p>书画等门类则让“轻”和“慢”变成可见的技术。动作幅度很小，却可能需要稳定判断和长时间练习。师徒间一句提醒、一次示范，比抽象地赞美匠心更能说明知识怎样传递：既有可讲述的步骤，也有依靠共同工作逐渐形成的经验。</p><h2 id="为什么工作之外的生活也重要" tabindex="-1">为什么工作之外的生活也重要 <a class="header-anchor" href="#为什么工作之外的生活也重要" aria-label="Permalink to &quot;为什么工作之外的生活也重要&quot;">​</a></h2><p>休息、聊天、院落里的片刻日常，让修复师摆脱神秘专家或奉献符号的单一形象。他们有职业耐心，也有普通人的节奏。这些片段不是专业内容的中断，而是在展示一项慢工作如何嵌入长期生活。</p><p>作品的长处是让观众愿意关注修复过程，局限是有限篇幅无法讲完各门类的技术与保护原则。看完参观博物馆时，不妨多看展签中的材质、年代与保存信息，想一想展柜背后还有哪些研究和维护。欣赏文物也就从“看见一件宝物”，延伸为理解一代代人如何承担保存它的责任。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢文博、手工艺和安静观察的人。三集体量适中，可完整观看后再参观博物馆；本条目明确指剧集版，不能混用2016年同名电影的时长和评分。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>修复师怎样在留下自己的劳动与尊重前人的痕迹之间取得平衡？慢工作如何改变对成就的理解？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://finance.sina.com.cn/tech/roll/2026-04-20/doc-inhvcmee0662433.shtml" target="_blank" rel="noopener noreferrer">新浪科技2026年报道转引的豆瓣评分</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://www.dpm.org.cn/classify_detail/234876.html" target="_blank" rel="noopener noreferrer">故宫博物院关于剧集与电影版本的介绍</a>：补充节目或版本背景。</li></ul><p><a href="./overview">返回纪录片片单</a> · <a href="./../overview">返回影视总览</a></p>',33)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
